INSERT INTO feature VALUES('component-judgement','modules','An import-connected component judged once','sibling-imports','implemented','ordinary',NULL,'The dispatcher lowers and checks each member of an import-connected component once and projects the verdict per file, so a base source is never re-judged inside each importer''s closure. Each importer is parsed whole once, its imports read from its import forms and confirmed on the component''s parse (#617).','surface-dispatcher','corpus/model/identity/','corpus/model/identity/circle-group.gandr','#436');
